CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- Better Auth uses its maintained adapter against these canonical identity tables.
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "twoFactorEnabled" boolean DEFAULT false);
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text UNIQUE NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id));
CREATE INDEX session_user_idx ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id), "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_user_idx ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE "rateLimit" (id text PRIMARY KEY, key text UNIQUE NOT NULL, count integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE TABLE "twoFactor" (id text PRIMARY KEY, secret text NOT NULL, "backupCodes" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id));
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('PLATFORM','CUSTOMER','PARTNER','FACILITY')), demo boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id), organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL CHECK(role IN ('PLATFORM_ADMIN','OPERATIONS_MANAGER','FINANCE_OFFICER','READ_ONLY_REVIEWER','CUSTOMER_OWNER','CUSTOMER_STAFF','PARTNER_DISPATCHER','COLLECTOR','FACILITY_MANAGER','RECEIVING_OFFICER')), active boolean NOT NULL DEFAULT true, UNIQUE(user_id,organization_id,role));
CREATE INDEX membership_org_idx ON memberships(organization_id);
CREATE TABLE native_credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id), session_id text NOT NULL REFERENCES session(id) ON DELETE CASCADE, access_hash text UNIQUE NOT NULL, refresh_hash text UNIQUE NOT NULL, family_id uuid NOT NULL, access_expires_at timestamptz NOT NULL, refresh_expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, country text NOT NULL DEFAULT 'LR', timezone text NOT NULL DEFAULT 'Africa/Monrovia', approved boolean NOT NULL DEFAULT false);
CREATE TABLE facilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, service_area_id uuid NOT NULL REFERENCES service_areas(id), active boolean NOT NULL DEFAULT false, accepted_materials text[] NOT NULL DEFAULT '{}', capacity_grams bigint NOT NULL CHECK(capacity_grams>0));
CREATE TABLE sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('SITE-'||upper(substr(gen_random_uuid()::text,1,8))), organization_id uuid NOT NULL REFERENCES organizations(id), service_area_id uuid REFERENCES service_areas(id), name text NOT NULL, category text NOT NULL, landmark text NOT NULL, contact text NOT NULL, operating_days integer[] NOT NULL, storage text NOT NULL, expected_grams bigint NOT NULL CHECK(expected_grams>=0), status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','WAITLIST','ASSESSED','QUOTED','SUBSCRIBED','ACTIVE','PAUSED')), timezone text NOT NULL DEFAULT 'Africa/Monrovia', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
CREATE INDEX sites_org_idx ON sites(organization_id,created_at);
CREATE TABLE baseline_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), description text NOT NULL, uncertainty text NOT NULL, evidence_reference text, beneficial_uses text NOT NULL DEFAULT 'Unknown; review required', recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), assessor_id text NOT NULL REFERENCES "user"(id), notes text NOT NULL, qualified boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('QT-'||upper(substr(gen_random_uuid()::text,1,8))), site_id uuid NOT NULL REFERENCES sites(id), status text NOT NULL DEFAULT 'DRAFT', currency text NOT NULL CHECK(currency IN ('USD','LRD')), amount_minor bigint NOT NULL CHECK(amount_minor>0), frequency_per_week integer NOT NULL CHECK(frequency_per_week BETWEEN 1 AND 7), allowance_grams bigint NOT NULL CHECK(allowance_grams>0), assumptions text NOT NULL, responsibilities text NOT NULL, service_window text NOT NULL, terms_version text NOT NULL, valid_until timestamptz NOT NULL, accepted_at timestamptz, accepted_by text REFERENCES "user"(id), snapshot jsonb, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quotation_id uuid UNIQUE NOT NULL REFERENCES quotations(id), snapshot jsonb NOT NULL, accepted_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE training_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), trained_name text NOT NULL, guidance_version text NOT NULL, trainer_id text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), agreement_id uuid UNIQUE NOT NULL REFERENCES agreements(id), status text NOT NULL DEFAULT 'ACTIVE', starts_on date NOT NULL, ends_on date, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_subscription ON subscriptions(site_id) WHERE status='ACTIVE';
CREATE TABLE schedule_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES subscriptions(id), site_id uuid NOT NULL REFERENCES sites(id), weekdays integer[] NOT NULL, timezone text NOT NULL, service_window text NOT NULL, paused boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, partner_organization_id uuid NOT NULL REFERENCES organizations(id), facility_id uuid NOT NULL REFERENCES facilities(id), service_area_id uuid NOT NULL REFERENCES service_areas(id), capacity_grams bigint NOT NULL CHECK(capacity_grams>0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('JOB-'||upper(substr(gen_random_uuid()::text,1,8))), schedule_id uuid NOT NULL REFERENCES schedule_rules(id), schedule_version integer NOT NULL, occurrence_date date NOT NULL, site_id uuid NOT NULL REFERENCES sites(id), organization_id uuid NOT NULL, state text NOT NULL DEFAULT 'SCHEDULED', route_id uuid REFERENCES routes(id), collector_id text REFERENCES "user"(id), partner_organization_id uuid REFERENCES organizations(id), facility_id uuid REFERENCES facilities(id), expected_grams bigint NOT NULL CHECK(expected_grams>=0), stop_order integer, reason text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(schedule_id,schedule_version,occurrence_date), FOREIGN KEY(site_id,organization_id) REFERENCES sites(id,organization_id));
CREATE INDEX jobs_org_date ON job_occurrences(organization_id,occurrence_date,state);
CREATE INDEX jobs_collector_date ON job_occurrences(collector_id,occurrence_date);
CREATE INDEX jobs_partner_idx ON job_occurrences(partner_organization_id);
CREATE TABLE collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid UNIQUE NOT NULL REFERENCES job_occurrences(id), collector_id text NOT NULL REFERENCES "user"(id), gross_grams bigint NOT NULL CHECK(gross_grams>=0), tare_grams bigint NOT NULL CHECK(tare_grams>=0), net_grams bigint NOT NULL CHECK(net_grams>=0 AND net_grams=gross_grams-tare_grams), measurement text NOT NULL CHECK(measurement IN ('MEASURED','ESTIMATED')), method text NOT NULL, material text NOT NULL, contamination text NOT NULL, residual_grams bigint NOT NULL DEFAULT 0 CHECK(residual_grams>=0), reason text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE manifests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('DEL-'||upper(substr(gen_random_uuid()::text,1,8))), partner_organization_id uuid NOT NULL REFERENCES organizations(id), facility_id uuid NOT NULL REFERENCES facilities(id), state text NOT NULL DEFAULT 'DRAFT', dispatched_by text NOT NULL REFERENCES "user"(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid NOT NULL REFERENCES manifests(id), collection_id uuid NOT NULL REFERENCES collections(id), grams bigint NOT NULL CHECK(grams>0), UNIQUE(manifest_id,collection_id));
CREATE INDEX delivery_collection_idx ON delivery_allocations(collection_id);
CREATE TABLE receiving_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid UNIQUE NOT NULL REFERENCES manifests(id), receiver_id text NOT NULL REFERENCES "user"(id), received_grams bigint NOT NULL CHECK(received_grams>=0), accepted_grams bigint NOT NULL CHECK(accepted_grams>=0), rejected_grams bigint NOT NULL CHECK(rejected_grams>=0), method text NOT NULL, allocation_method text NOT NULL, proof_reference text NOT NULL, evidence_status text NOT NULL DEFAULT 'SUBMITTED_NOT_REVIEWED', created_at timestamptz NOT NULL DEFAULT now(), CHECK(accepted_grams+rejected_grams=received_grams));
CREATE TABLE receiving_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receiving_id uuid NOT NULL REFERENCES receiving_records(id), collection_id uuid NOT NULL REFERENCES collections(id), accepted_grams bigint NOT NULL CHECK(accepted_grams>=0), rejected_grams bigint NOT NULL CHECK(rejected_grams>=0), UNIQUE(receiving_id,collection_id));
CREATE TABLE reconciliation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid UNIQUE NOT NULL REFERENCES manifests(id), discrepancy_grams bigint NOT NULL, status text NOT NULL DEFAULT 'OPEN', reason text, reviewer_id text REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE residuals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receiving_id uuid REFERENCES receiving_records(id), job_id uuid REFERENCES job_occurrences(id), organization_id uuid NOT NULL REFERENCES organizations(id), grams bigint NOT NULL CHECK(grams>0), reason text NOT NULL, responsible_provider text NOT NULL, destination text, evidence_reference text, status text NOT NULL DEFAULT 'DESTINATION_PENDING', created_at timestamptz NOT NULL DEFAULT now(), CHECK(receiving_id IS NOT NULL OR job_id IS NOT NULL));
CREATE TABLE batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), facility_id uuid NOT NULL REFERENCES facilities(id), name text NOT NULL, state text NOT NULL DEFAULT 'CREATED', allocation_method text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE batch_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES batches(id), receiving_allocation_id uuid NOT NULL REFERENCES receiving_allocations(id), grams bigint NOT NULL CHECK(grams>0), UNIQUE(batch_id,receiving_allocation_id));
CREATE TABLE process_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES batches(id), actor_id text NOT NULL REFERENCES "user"(id), notes text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outputs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES batches(id), grams bigint NOT NULL CHECK(grams>=0), quality_status text NOT NULL, evidence_reference text, ownership text NOT NULL, intended_use text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('INV-'||upper(substr(gen_random_uuid()::text,1,8))), organization_id uuid NOT NULL REFERENCES organizations(id), site_id uuid NOT NULL, agreement_id uuid NOT NULL REFERENCES agreements(id), status text NOT NULL DEFAULT 'ISSUED', currency text NOT NULL CHECK(currency IN ('USD','LRD')), total_minor bigint NOT NULL CHECK(total_minor>0), paid_minor bigint NOT NULL DEFAULT 0 CHECK(paid_minor>=0 AND paid_minor<=total_minor), period_start date NOT NULL, period_end date NOT NULL, due_date date NOT NULL, terms_snapshot jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(site_id,organization_id) REFERENCES sites(id,organization_id), UNIQUE(agreement_id,period_start,period_end), CHECK(period_end>=period_start));
CREATE INDEX invoices_org_idx ON invoices(organization_id,due_date,status);
CREATE TABLE invoice_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), description text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_minor bigint NOT NULL CHECK(unit_minor>=0), total_minor bigint NOT NULL CHECK(total_minor=quantity*unit_minor));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), organization_id uuid NOT NULL REFERENCES organizations(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL CHECK(currency IN ('USD','LRD')), reference text NOT NULL, duplicate_flag boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'PENDING_REVIEW', submitted_by text NOT NULL REFERENCES "user"(id), reviewed_by text REFERENCES "user"(id), review_reason text, created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz);
CREATE INDEX payment_reference_idx ON payments(lower(reference),currency);
CREATE TABLE allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid UNIQUE NOT NULL REFERENCES payments(id), invoice_id uuid NOT NULL REFERENCES invoices(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deposits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), currency text NOT NULL CHECK(currency IN ('USD','LRD')), amount_minor bigint NOT NULL CHECK(amount_minor>0), status text NOT NULL DEFAULT 'LIABILITY', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partner_charges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), route_id uuid REFERENCES routes(id), currency text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), rate_version text NOT NULL, evidence_reference text NOT NULL, status text NOT NULL DEFAULT 'SUBMITTED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), charge_id uuid UNIQUE NOT NULL REFERENCES partner_charges(id), organization_id uuid NOT NULL REFERENCES organizations(id), status text NOT NULL DEFAULT 'APPROVED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE route_costs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES routes(id), amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency text NOT NULL, basis text NOT NULL CHECK(basis IN ('ACTUAL','ESTIMATED')), category text NOT NULL, source text NOT NULL, period_start date NOT NULL, period_end date NOT NULL);
CREATE TABLE containers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), site_id uuid REFERENCES sites(id), reference text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'AVAILABLE', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE complaints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('CASE-'||upper(substr(gen_random_uuid()::text,1,8))), site_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'OPEN', assigned_to text REFERENCES "user"(id), response_due_at timestamptz NOT NULL DEFAULT (now()+interval '48 hours'), resolution_reason text, created_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(site_id,organization_id) REFERENCES sites(id,organization_id));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id uuid NOT NULL REFERENCES complaints(id), actor_id text NOT NULL REFERENCES "user"(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), uploader_id text NOT NULL REFERENCES "user"(id), object_key text UNIQUE NOT NULL, filename text NOT NULL, content_type text NOT NULL, byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 10000000), status text NOT NULL DEFAULT 'UPLOAD_PENDING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id text REFERENCES "user"(id), title text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text NOT NULL REFERENCES "user"(id), organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL, action text NOT NULL, target_id text NOT NULL, reason text NOT NULL, changes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_date ON audit_events(organization_id,created_at);
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), entity_id text NOT NULL, entity_version integer NOT NULL, type text NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, dead_letter boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_events(next_attempt_at) WHERE published_at IS NULL AND NOT dead_letter;
CREATE TABLE idempotency_records (user_id text NOT NULL REFERENCES "user"(id), organization_id uuid NOT NULL REFERENCES organizations(id), key text NOT NULL, payload_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,organization_id,key));
CREATE TABLE webhook_events (provider text NOT NULL, event_id text NOT NULL, payload_hash text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,event_id));
CREATE TABLE settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings VALUES ('pilot', '{"country":"LR","timezone":"Africa/Monrovia","currencies":["USD","LRD"],"emissionsEnabled":false,"compostSalesEnabled":false,"reconciliationToleranceGrams":500,"billingRole":"COORDINATOR_REQUIRES_AGREEMENT_REVIEW"}', now());
-- Evidence and financial history are append-only to application SQL; corrections need dedicated reviewed records.
CREATE FUNCTION forbid_evidence_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Evidence cannot be deleted'; END $$;
CREATE TRIGGER collections_no_delete BEFORE DELETE ON collections FOR EACH ROW EXECUTE FUNCTION forbid_evidence_delete();
CREATE TRIGGER receiving_no_delete BEFORE DELETE ON receiving_records FOR EACH ROW EXECUTE FUNCTION forbid_evidence_delete();
CREATE TRIGGER invoices_no_delete BEFORE DELETE ON invoices FOR EACH ROW EXECUTE FUNCTION forbid_evidence_delete();
CREATE TRIGGER payments_no_delete BEFORE DELETE ON payments FOR EACH ROW EXECUTE FUNCTION forbid_evidence_delete();
CREATE TRIGGER audit_no_delete BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION forbid_evidence_delete();
